CREATE EXTENSION IF NOT EXISTS postgis;
DO $$ BEGIN CREATE TYPE agency_type AS ENUM ('municipal_roads','water_sewer','electricity','telecom','gas','metro','pwd_nhai','other'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE work_category AS ENUM ('road_cut','resurfacing','water_pipeline','sewer','drainage','electricity','telecom_duct','gas_pipeline','metro','footpath','other'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE work_status AS ENUM ('planned','permitted','ongoing','paused','completed','restoration_verified','closed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE disruption_type AS ENUM ('none','restricted_access','partial_closure','full_closure'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE evidence_kind AS ENUM ('progress','restoration','before','after'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE permit_type AS ENUM ('road_cut','row_utility','closure_noc'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE permit_status AS ENUM ('draft','submitted','pending_coordination','approved','rejected','held','expired'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE deposit_status AS ENUM ('none','held','released','forfeited'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE conflict_type AS ENUM ('overlap','recent_resurfacing'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE conflict_status AS ENUM ('open','resolved'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE conflict_detected_by AS ENUM ('submission','nightly_scan'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE conflict_action AS ENUM ('coordinate_dates','combine_work','reschedule','justify_both'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE feedback_kind AS ENUM ('question','complaint','observation','still_ongoing_yes','still_ongoing_no'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE feedback_status AS ENUM ('open','acknowledged','in_progress','resolved','closed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE moderation_status AS ENUM ('pending','approved','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE follow_channel AS ENUM ('sms','whatsapp','email','push','console'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE notification_status AS ENUM ('queued','sent','suppressed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS tenant(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, center geometry(Point,4326));
CREATE TABLE IF NOT EXISTS zone(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, name text NOT NULL);
CREATE TABLE IF NOT EXISTS ward(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, zone_id uuid REFERENCES zone, name text NOT NULL, boundary geometry(MultiPolygon,4326));
CREATE TABLE IF NOT EXISTS agency(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, name text NOT NULL, type agency_type NOT NULL, short_code text NOT NULL);
CREATE TABLE IF NOT EXISTS app_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, agency_id uuid REFERENCES agency, name text NOT NULL, email text UNIQUE, phone text, password_hash text, role text NOT NULL, ward_id uuid REFERENCES ward, zone_id uuid REFERENCES zone, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS escalation_level(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, agency_id uuid REFERENCES agency, level int NOT NULL, role text NOT NULL);
CREATE TABLE IF NOT EXISTS work(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, ref_no text UNIQUE NOT NULL, title text NOT NULL, purpose text, category work_category NOT NULL, status work_status NOT NULL DEFAULT 'planned', agency_id uuid NOT NULL REFERENCES agency, contractor_name text, contractor_public boolean NOT NULL DEFAULT true, contact_name text, contact_phone text, contact_email text, contact_channel text, road_name text, ward_id uuid REFERENCES ward, geometry geometry(Geometry,4326), length_m double precision, planned_start date, original_target_end date, current_target_end date, actual_start date, actual_end date, pct_complete int NOT NULL DEFAULT 0 CHECK (pct_complete BETWEEN 0 AND 100), disruption_type disruption_type NOT NULL DEFAULT 'none', disruption_note text, is_public boolean NOT NULL DEFAULT true, public_flags jsonb NOT NULL DEFAULT '{}'::jsonb, resurfaced_on date, last_update_at timestamptz, restoration_verified_at timestamptz, created_by uuid REFERENCES app_user, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS work_milestone(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_id uuid NOT NULL REFERENCES work ON DELETE CASCADE, name text NOT NULL, planned_date date, actual_date date, pct int NOT NULL DEFAULT 0, sort int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS work_date_revision(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_id uuid NOT NULL REFERENCES work ON DELETE CASCADE, old_target date NOT NULL, new_target date NOT NULL, reason_code text NOT NULL, explanation text NOT NULL, by_user uuid REFERENCES app_user, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS work_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_id uuid NOT NULL REFERENCES work ON DELETE CASCADE, from_status work_status, to_status work_status NOT NULL, reason_code text, explanation text, by_user uuid REFERENCES app_user, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS work_update(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_id uuid NOT NULL REFERENCES work ON DELETE CASCADE, text text NOT NULL, pct_complete int CHECK (pct_complete BETWEEN 0 AND 100), by_user uuid REFERENCES app_user, at timestamptz NOT NULL DEFAULT now(), is_public boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_id uuid NOT NULL REFERENCES work ON DELETE CASCADE, work_update_id uuid REFERENCES work_update, file_path text NOT NULL, public_path text, taken_at timestamptz, lat double precision, lon double precision, exif_ok boolean NOT NULL DEFAULT false, uploaded_by uuid REFERENCES app_user, verified_by uuid REFERENCES app_user, verified_at timestamptz, kind evidence_kind NOT NULL);
CREATE TABLE IF NOT EXISTS permit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_id uuid NOT NULL REFERENCES work, type permit_type NOT NULL, status permit_status NOT NULL DEFAULT 'draft', applied_at timestamptz NOT NULL DEFAULT now(), approved_by uuid REFERENCES app_user, approved_at timestamptz, deposit_amount numeric(12,2), deposit_status deposit_status NOT NULL DEFAULT 'none', valid_from date, valid_to date, note text);
CREATE TABLE IF NOT EXISTS conflict_alert(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, work_a uuid NOT NULL REFERENCES work, work_b uuid NOT NULL REFERENCES work, type conflict_type NOT NULL, overlap_days int, days_since_resurfacing int, distance_m numeric, status conflict_status NOT NULL DEFAULT 'open', detected_at timestamptz NOT NULL DEFAULT now(), detected_by conflict_detected_by NOT NULL);
CREATE TABLE IF NOT EXISTS conflict_decision(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, alert_id uuid NOT NULL REFERENCES conflict_alert, action conflict_action NOT NULL, note text NOT NULL, decided_by uuid REFERENCES app_user, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feedback_ticket(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, ref_no text UNIQUE NOT NULL, work_id uuid NOT NULL REFERENCES work, resident_id uuid NOT NULL REFERENCES app_user, kind feedback_kind NOT NULL, text text NOT NULL, photo_path text, lat double precision, lon double precision, status feedback_status NOT NULL DEFAULT 'open', current_level int NOT NULL DEFAULT 1, assigned_to uuid REFERENCES app_user, is_public boolean NOT NULL DEFAULT false, moderation moderation_status NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), last_response_at timestamptz, escalated_at timestamptz);
CREATE TABLE IF NOT EXISTS ticket_event(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, ticket_id uuid NOT NULL REFERENCES feedback_ticket ON DELETE CASCADE, status feedback_status, responder_id uuid REFERENCES app_user, message text, is_public boolean NOT NULL DEFAULT false, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS follow_subscription(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, resident_id uuid NOT NULL REFERENCES app_user, work_id uuid REFERENCES work, ward_id uuid REFERENCES ward, channel follow_channel NOT NULL DEFAULT 'console', active boolean NOT NULL DEFAULT true, CHECK ((work_id IS NOT NULL)::int + (ward_id IS NOT NULL)::int = 1));
CREATE TABLE IF NOT EXISTS notification(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant, user_id uuid NOT NULL REFERENCES app_user, work_id uuid REFERENCES work, kind text NOT NULL, title text NOT NULL, body text NOT NULL, link text NOT NULL, channel follow_channel NOT NULL DEFAULT 'console', status notification_status NOT NULL DEFAULT 'queued', dedupe_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, UNIQUE(tenant_id,dedupe_key));
CREATE TABLE IF NOT EXISTS outbox_event(id bigserial PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenant, type text NOT NULL, version int NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenant, actor_id uuid REFERENCES app_user, action text NOT NULL, entity text NOT NULL, entity_id text, before jsonb, after jsonb, at timestamptz NOT NULL DEFAULT now(), prev_hash text NOT NULL, hash text NOT NULL);
CREATE TABLE IF NOT EXISTS city_config(tenant_id uuid PRIMARY KEY REFERENCES tenant, buffer_m numeric NOT NULL DEFAULT 15, lookback_months int NOT NULL DEFAULT 24, overdue_days int NOT NULL DEFAULT 7, sla_day_ae int NOT NULL DEFAULT 3, sla_day_ee int NOT NULL DEFAULT 7, sla_day_se int NOT NULL DEFAULT 14, sla_time_scale numeric NOT NULL DEFAULT 1, reason_codes jsonb NOT NULL DEFAULT '["weather","material_delay","contractor_delay","utility_clash","permit_delay","funds_delay","design_change","public_safety","court_order","force_majeure","other"]'::jsonb, features jsonb NOT NULL DEFAULT '{}'::jsonb);

CREATE INDEX IF NOT EXISTS ward_boundary_gix ON ward USING gist(boundary);
CREATE INDEX IF NOT EXISTS work_geometry_gix ON work USING gist(geometry);
CREATE INDEX IF NOT EXISTS work_dates_gix ON work USING gist(daterange(planned_start,current_target_end,'[]'));
CREATE INDEX IF NOT EXISTS work_status_idx ON work(status);
CREATE INDEX IF NOT EXISTS work_agency_idx ON work(agency_id);
CREATE INDEX IF NOT EXISTS work_ward_idx ON work(ward_id);
CREATE INDEX IF NOT EXISTS ticket_work_idx ON feedback_ticket(work_id);
CREATE INDEX IF NOT EXISTS outbox_unpublished_idx ON outbox_event(created_at) WHERE published_at IS NULL;

CREATE OR REPLACE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_log is append-only'; END $$;
DROP TRIGGER IF EXISTS audit_log_no_update_delete ON audit_log;
CREATE TRIGGER audit_log_no_update_delete BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
